        });

    let database_url = std::env::var("DATABASE_URL")
        .unwrap_or_else(|_| "postgres://localhost/app".to_string());

    let feature_flags: Vec<String> = std::env::var("APP_FEATURES")
        .map(|value| {
            value
                .split(',')
                .map(str::trim)
                .filter(|flag| !flag.is_empty())
                .map(String::from)
